<?php get_header(); ?>
<div class="wrap layout"><main id="main">
<header class="intro"><?php if(is_search()): ?><span class="eyebrow">Busca</span><h1><?php printf(esc_html__('Resultados para: %s','allg-editorial'),esc_html(get_search_query())); ?></h1><?php elseif(is_archive()): the_archive_title('<h1>','</h1>'); the_archive_description('<div>','</div>'); else: ?><span class="eyebrow">Seu próximo assunto favorito</span><h1><?php echo esc_html(get_theme_mod('allge_heading','Boas histórias começam aqui.')); ?></h1><p><?php echo esc_html(get_theme_mod('allge_description','Conteúdo selecionado para descobrir, aprender e ir além.')); ?></p><?php endif; ?></header>
<?php if(have_posts()): ?><div class="cards"><?php $allge_index=0; while(have_posts()): the_post(); $featured=is_home() && !is_paged() && $allge_index===0; ?><article id="post-<?php the_ID(); ?>" <?php post_class('card'.($featured?' featured':'')); ?>>
<a class="card-image" href="<?php the_permalink(); ?>" aria-label="<?php the_title_attribute(); ?>"><?php if(has_post_thumbnail()): the_post_thumbnail('allge-card',array('loading'=>$featured?'eager':'lazy','fetchpriority'=>$featured?'high':'auto','decoding'=>'async','sizes'=>$featured?'(max-width: 600px) calc(100vw - 64px), (max-width: 900px) calc(100vw - 88px), (max-width: 1240px) calc(100vw - 436px), 804px':'(max-width: 600px) calc(100vw - 32px), (max-width: 900px) calc((100vw - 66px) / 2), (max-width: 1240px) calc((100vw - 414px) / 2), 413px')); else: ?><span class="image-placeholder" aria-hidden="true">✦</span><?php endif; ?></a>
<?php allge_categories(); ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div class="card-meta"><?php echo esc_html(get_the_author()); ?> &middot; <time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date()); ?></time></div><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),25)); ?></p><a href="<?php the_permalink(); ?>"><?php esc_html_e('Continuar lendo →','allg-editorial'); ?></a></article><?php $allge_index++; endwhile; ?></div><?php the_posts_pagination(array('mid_size'=>1,'prev_text'=>'← Anterior','next_text'=>'Próxima →')); ?>
<?php else: ?><section class="empty-state"><h2><?php esc_html_e('Nenhum conteúdo encontrado','allg-editorial'); ?></h2><p><?php esc_html_e('Tente outra busca ou volte em breve para ler as novidades.','allg-editorial'); ?></p><?php get_search_form(); ?></section><?php endif; ?></main><?php get_sidebar(); ?></div><?php get_footer(); ?>
